import { readFileSync } from 'node:fs';

export type Cell = number | string | null;
export interface DataRow {
  number: number;
  values: Record<string, Cell>;
}
export interface Column {
  name: string;
  categorical: boolean;
}
export interface Frame {
  columns: Column[];
  rows: DataRow[];
}
export interface Parameters {
  tolerance: number;
  alpha: number;
  confidence: number;
  leverage: number;
  studentized: number;
  cook: number;
  dffits: number;
  vif: number;
  durbinWatson: number;
  heterogeneity: number;
  normality: number;
  best: number;
  width: number;
  height: number;
  range: number;
}
function readFrame(path: string, kinds?: Column[]): Frame {
  const lines = readFileSync(path, 'ascii').trimEnd().split('\n');
  const names = lines[0].split(',');
  const cells = lines.slice(1).map((line) => line.split(','));
  const columns = names.map((name, c) => ({
    name,
    categorical: kinds
      ? kinds.find((column) => column.name === name)!.categorical
      : cells.some((row) => row[c] !== 'NA' && /^[A-Z]/.test(row[c])),
  }));
  const rows = cells.map((row, i) => {
    const values: Record<string, Cell> = {};
    columns.forEach((column, c) => {
      values[column.name] = row[c] === 'NA' ? null : column.categorical ? row[c] : +row[c];
    });
    return { number: i + 1, values };
  });
  return { columns, rows };
}
export function numberValue(row: DataRow, column: string): number {
  const value = row.values[column];
  if (typeof value !== 'number') throw new Error(`Missing numeric value ${column}`);
  return value;
}
export function readInputs(): {
  data: Frame;
  predictions: Frame;
  formulas: string[];
  params: Parameters;
} {
  const data = readFrame('input/data.csv');
  const predictions = readFrame('input/predict.csv', data.columns);
  const formulas = readFileSync('input/model.txt', 'ascii').trimEnd().split('\n');
  const rows = readFileSync('input/params.txt', 'ascii')
    .trimEnd()
    .split('\n')
    .map((line) => line.split(' ').slice(1).map(Number));
  const params: Parameters = {
    tolerance: rows[0][0],
    alpha: rows[1][0],
    confidence: rows[2][0],
    leverage: rows[3][0],
    studentized: rows[4][0],
    cook: rows[5][0],
    dffits: rows[6][0],
    vif: rows[7][0],
    durbinWatson: rows[8][0],
    heterogeneity: rows[9][0],
    normality: rows[10][0],
    best: rows[11][0],
    width: rows[12][0],
    height: rows[12][1],
    range: rows[12][2],
  };
  return { data, predictions, formulas, params };
}

import type { Parameters } from './dataframe.ts';
import { pChi } from './inference.ts';
import { fit, type Fit } from './qr_solver.ts';

export interface RowDiagnostics {
  standardized: number;
  studentized: number;
  cooks: number;
  dffits: number;
  flags: string;
  dfbetas: number[];
}
export interface Diagnostics {
  rows: RowDiagnostics[];
  dw: number;
  bp: number;
  bpDf: number;
  bpP: number;
  skewness: number;
  kurtosis: number;
  jb: number;
  jbP: number;
}
export function diagnose(
  model: Fit,
  x: number[][],
  sigma: number,
  df: number,
  params: Parameters,
): Diagnostics {
  const n = x.length;
  const r = model.rank;
  const rows = model.weightedResiduals.map((eps, i) => {
    const h = model.leverage[i];
    const standardized = eps / (sigma * Math.sqrt(1 - h));
    const studentized = standardized * Math.sqrt((df - 1) / (df - standardized * standardized));
    const cooks = (standardized * standardized * h) / (r * (1 - h));
    const dffits = studentized * Math.sqrt(h / (1 - h));
    const flags =
      (h > (params.leverage * r) / n ? 'H' : '') +
      (Math.abs(studentized) > params.studentized ? 'O' : '') +
      (cooks > params.cook / n ? 'C' : '') +
      (Math.abs(dffits) > params.dffits * Math.sqrt(r / n) ? 'F' : '');
    const deletedSigma = sigma * Math.sqrt((df - standardized * standardized) / (df - 1));
    const dfbetas = model.g[i].map(
      (g, k) => (g * eps) / (1 - h) / (deletedSigma * Math.sqrt(model.varianceFactors[k])),
    );
    return { standardized, studentized, cooks, dffits, flags: flags || '-', dfbetas };
  });
  let dwNumerator = 0;
  for (let i = 1; i < n; i++) {
    const delta = model.weightedResiduals[i] - model.weightedResiduals[i - 1];
    dwNumerator += delta * delta;
  }
  const dw = dwNumerator / model.rss;
  const squares = model.weightedResiduals.map((eps) => eps * eps);
  const rawAccepted = x.map((row) => model.accepted.map((j) => row[j]));
  const auxiliary = fit(rawAccepted, squares, Array<number>(n).fill(1), params.tolerance);
  const meanSquare = squares.reduce((a, b) => a + b, 0) / n;
  let tss = 0;
  for (const value of squares) tss += (value - meanSquare) * (value - meanSquare);
  const bp = n * (1 - auxiliary.rss / tss);
  const bpDf = auxiliary.rank - 1;
  const bpP = pChi(bp, bpDf);
  const mean = model.weightedResiduals.reduce((a, b) => a + b, 0) / n;
  let sum2 = 0;
  let sum3 = 0;
  let sum4 = 0;
  for (const eps of model.weightedResiduals) {
    const delta = eps - mean;
    sum2 += delta * delta;
    sum3 += delta * delta * delta;
    sum4 += delta * delta * delta * delta;
  }
  const m2 = sum2 / n;
  const m3 = sum3 / n;
  const m4 = sum4 / n;
  const skewness = m3 / (m2 * Math.sqrt(m2));
  const kurtosis = m4 / (m2 * m2);
  const jb = (n / 6) * (skewness * skewness + ((kurtosis - 3) * (kurtosis - 3)) / 4);
  return { rows, dw, bp, bpDf, bpP, skewness, kurtosis, jb, jbP: pChi(jb, 2) };
}

import { numberValue, type DataRow } from './dataframe.ts';

export type Factor =
  | { name: string; column: string; kind: 'numeric' }
  | { name: string; column: string; kind: 'categorical' }
  | { name: string; column: string; kind: 'power'; power: number };
export interface Term {
  name: string;
  factors: Factor[];
}
export interface Model {
  formula: string;
  response: string;
  weight?: string;
  terms: Term[];
}
export interface Component {
  name: string;
  factor: Factor;
  level?: string;
}
export interface DesignColumn {
  name: string;
  term?: number;
  components: Component[];
}
export function parseFormula(line: string): Model {
  const [formula, weight] = line.split(' weights=');
  const [response, rhs] = formula.split(' ~ ');
  const terms: Term[] = [];
  const factor = (name: string): Factor => {
    if (name.startsWith('C(')) return { name, column: name.slice(2, -1), kind: 'categorical' };
    if (name.startsWith('I(')) {
      const [column, power] = name.slice(2, -1).split('^');
      return { name, column, kind: 'power', power: +power };
    }
    return { name, column: name, kind: 'numeric' };
  };
  const seen = new Set<string>();
  const append = (factors: Factor[]) => {
    const key = factors
      .map((f) => f.name)
      .sort()
      .join('|');
    if (!seen.has(key)) {
      seen.add(key);
      terms.push({ name: factors.map((f) => f.name).join(':'), factors });
    }
  };
  for (const expression of rhs.split(' + ')) {
    if (!expression.includes('*')) append(expression.split(':').map(factor));
    else {
      const factors = expression.split('*').map(factor);
      const subsets = (size: number, start: number, chosen: Factor[]): void => {
        if (chosen.length === size) {
          append(chosen);
          return;
        }
        for (let i = start; i < factors.length; i++) subsets(size, i + 1, [...chosen, factors[i]]);
      };
      for (let size = 1; size <= factors.length; size++) subsets(size, 0, []);
    }
  }
  return { formula, response, weight, terms };
}
export const contained = (a: Term, b: Term) =>
  a.factors.length < b.factors.length &&
  a.factors.every((f) => b.factors.some((g) => f.name === g.name));
export const factorColumns = (model: Model) => [
  ...new Set(model.terms.flatMap((term) => term.factors.map((f) => f.column))),
];
export function variables(model: Model): string[] {
  return [
    ...new Set([...factorColumns(model), model.response, ...(model.weight ? [model.weight] : [])]),
  ];
}
export function findLevels(model: Model, rows: DataRow[]): Map<string, string[]> {
  const levels = new Map<string, string[]>();
  for (const term of model.terms) {
    for (const factor of term.factors) {
      if (factor.kind === 'categorical' && !levels.has(factor.column)) {
        levels.set(
          factor.column,
          [
            ...new Set(
              rows
                .map((row) => row.values[factor.column])
                .filter((value): value is string => typeof value === 'string'),
            ),
          ].sort(),
        );
      }
    }
  }
  return levels;
}
export function designColumns(model: Model, levels: Map<string, string[]>): DesignColumn[] {
  const columns: DesignColumn[] = [{ name: '(Intercept)', components: [] }];
  model.terms.forEach((term, t) => {
    let tuples: Component[][] = [[]];
    for (const factor of term.factors) {
      const components: Component[] =
        factor.kind === 'categorical'
          ? levels
              .get(factor.column)!
              .slice(1)
              .map((level) => ({ name: factor.name + level, factor, level }))
          : [{ name: factor.name, factor }];
      tuples = components.flatMap((component) => tuples.map((tuple) => [...tuple, component]));
    }
    for (const components of tuples) {
      columns.push({ name: components.map((c) => c.name).join(':'), term: t, components });
    }
  });
  return columns;
}
export function columnValue(column: DesignColumn, row: DataRow): number {
  const componentValue = (component: Component): number => {
    const factor = component.factor;
    if (factor.kind === 'categorical') return row.values[factor.column] === component.level ? 1 : 0;
    const value = numberValue(row, factor.column);
    return factor.kind === 'numeric'
      ? value
      : factor.power === 2
        ? value * value
        : value * value * value;
  };
  if (!column.components.length) return 1;
  let value = componentValue(column.components[0]);
  for (const component of column.components.slice(1)) value = value * componentValue(component);
  return value;
}
export function predictable(model: Model, levels: Map<string, string[]>, row: DataRow): boolean {
  return factorColumns(model).every((column) => {
    const value = row.values[column];
    return (
      value !== null &&
      value !== undefined &&
      (!levels.has(column) || (typeof value === 'string' && levels.get(column)!.includes(value)))
    );
  });
}
export const formulaText = (model: Model, terms: number[]) =>
  model.response + ' ~ ' + (terms.map((t) => model.terms[t].name).join(' + ') || '1');

function logGamma(x: number): number {
  const coefficients = [
    76.18009172947146, -86.50532032941677, 24.01409824083091, -1.231739572450155,
    0.001208650973866179, -0.000005395239384953,
  ];
  const t = x + 5.5;
  const bigT = t - (x + 0.5) * Math.log(t);
  let sum = 1.000000000190015;
  coefficients.forEach((coefficient, j) => {
    sum += coefficient / (x + (j + 1));
  });
  return -bigT + Math.log((2.5066282746310005 * sum) / x);
}
const small = (value: number) => (Math.abs(value) < 1e-300 ? 1e-300 : value);
function continuedBeta(a: number, b: number, x: number): number {
  let c = 1;
  let d = 1 / small(1 - ((a + b) * x) / (a + 1));
  let h = d;
  for (let m = 1; m <= 1000; m++) {
    let q = (m * (b - m) * x) / ((a - 1 + 2 * m) * (a + 2 * m));
    d = 1 / small(1 + q * d);
    c = small(1 + q / c);
    h = h * (d * c);
    q = (-(a + m) * (a + b + m) * x) / ((a + 2 * m) * (a + 1 + 2 * m));
    d = 1 / small(1 + q * d);
    c = small(1 + q / c);
    const delta = d * c;
    h = h * delta;
    if (Math.abs(delta - 1) < 1e-15) break;
  }
  return h;
}
export function betaI(x: number, a: number, b: number): number {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  const factor = Math.exp(
    logGamma(a + b) - logGamma(a) - logGamma(b) + a * Math.log(x) + b * Math.log(1 - x),
  );
  return x < (a + 1) / (a + b + 2)
    ? (factor * continuedBeta(a, b, x)) / a
    : 1 - (factor * continuedBeta(b, a, 1 - x)) / b;
}
export function gammaQ(a: number, x: number): number {
  if (x === 0) return 1;
  const factor = Math.exp(-x + a * Math.log(x) - logGamma(a));
  if (x < a + 1) {
    let t = 1 / a;
    let sum = t;
    let e = a;
    for (let i = 0; i < 1000; i++) {
      e = e + 1;
      t = t * (x / e);
      sum = sum + t;
      if (Math.abs(t) < Math.abs(sum) * 1e-15) break;
    }
    return 1 - sum * factor;
  }
  let beta = x + 1 - a;
  let c = 1 / 1e-300;
  let d = 1 / beta;
  let h = d;
  for (let i = 1; i <= 1000; i++) {
    const q = -i * (i - a);
    beta = beta + 2;
    d = 1 / small(q * d + beta);
    c = small(beta + q / c);
    const delta = d * c;
    h = h * delta;
    if (Math.abs(delta - 1) < 1e-15) break;
  }
  return factor * h;
}
export const pT = (t: number, df: number) => betaI(df / (df + t * t), df / 2, 0.5);
export const pF = (value: number, d1: number, d2: number) =>
  betaI(d2 / (d2 + d1 * value), d2 / 2, d1 / 2);
export const pChi = (value: number, df: number) => gammaQ(df / 2, value / 2);
export function tQuantile(confidence: number, df: number): number {
  let lo = 0;
  let hi = 1000;
  for (let i = 0; i < 100; i++) {
    const mid = (lo + hi) / 2;
    if (pT(mid, df) > 1 - confidence) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}
export const significance = (p: number | undefined) =>
  p === undefined ? '' : p < 0.001 ? '***' : p < 0.01 ? '**' : p < 0.05 ? '*' : p < 0.1 ? '.' : '';
export function format(value: number | undefined): string {
  if (value === undefined) return 'NA';
  if (Math.abs(value) >= 1e21) return `${BigInt(value)}.0000`;
  const text = value.toFixed(4);
  return +text === 0 ? '0.0000' : text;
}
export const formatP = (p: number | undefined) =>
  p === undefined ? 'NA' : p < 0.0001 ? '<0.0001' : format(p);

import { writeFileSync } from 'node:fs';
import { numberValue, readInputs, type DataRow } from './dataframe.ts';
import { diagnose, type Diagnostics } from './diagnostics.ts';
import {
  columnValue,
  contained,
  designColumns,
  findLevels,
  formulaText,
  parseFormula,
  predictable,
  variables,
  type DesignColumn,
  type Model,
} from './formula.ts';
import { format as f, formatP as fp, pF, pT, significance, tQuantile } from './inference.ts';
import { fit, type Fit } from './qr_solver.ts';

const { data, predictions, formulas, params } = readInputs();
const sum = (values: number[]) => values.reduce((a, b) => a + b, 0);
interface Statistics {
  df: number;
  sigma: number;
  tss: number;
  r2: number;
  adjusted: number;
  f?: number;
  fP?: number;
  loglik: number;
  aic: number;
  bic: number;
  press: number;
  predicted: number;
  quantiles: number[];
  critical: number;
}
function statistics(model: Fit, y: number[], weights: number[]): Statistics {
  const n = y.length;
  const r = model.rank;
  const df = n - r;
  const sigma = Math.sqrt(model.rss / df);
  const weightSum = sum(weights);
  const mean = sum(y.map((value, i) => weights[i] * value)) / weightSum;
  const tss = sum(y.map((value, i) => weights[i] * (value - mean) * (value - mean)));
  const r2 = 1 - model.rss / tss;
  const adjusted = 1 - ((1 - r2) * (n - 1)) / df;
  const f = r > 1 ? (tss - model.rss) / (r - 1) / (model.rss / df) : undefined;
  const loglik =
    0.5 *
    (sum(weights.map(Math.log)) -
      n * (Math.log(2 * 3.141592653589793) + 1 - Math.log(n) + Math.log(model.rss)));
  const aic = -2 * loglik + 2 * (r + 1);
  const bic = -2 * loglik + Math.log(n) * (r + 1);
  const press = sum(
    model.weightedResiduals.map(
      (eps, i) => (eps / (1 - model.leverage[i])) * (eps / (1 - model.leverage[i])),
    ),
  );
  const residuals = [...model.weightedResiduals].sort((a, b) => a - b);
  const quantiles = [0, 0.25, 0.5, 0.75, 1].map((proportion) => {
    const g = (n - 1) * proportion;
    const k = Math.floor(g);
    return k + 1 < n ? residuals[k] + (g - k) * (residuals[k + 1] - residuals[k]) : residuals[k];
  });
  return {
    df,
    sigma,
    tss,
    r2,
    adjusted,
    f,
    fP: f === undefined ? undefined : pF(f, r - 1, df),
    loglik,
    aic,
    bic,
    press,
    predicted: 1 - press / tss,
    quantiles,
    critical: tQuantile(params.confidence, df),
  };
}
interface ModelContext {
  model: Model;
  rows: DataRow[];
  levels: Map<string, string[]>;
  columns: DesignColumn[];
  x: number[][];
  y: number[];
  weights: number[];
  fit: Fit;
  stats: Statistics;
  diagnostics: Diagnostics;
}
const models: ModelContext[] = formulas.map((line) => {
  const model = parseFormula(line);
  const required = variables(model);
  const rows = data.rows.filter((row) => required.every((name) => row.values[name] !== null));
  const levels = findLevels(model, rows);
  const columns = designColumns(model, levels);
  const x = rows.map((row) => columns.map((column) => columnValue(column, row)));
  const y = rows.map((row) => numberValue(row, model.response));
  const weights = rows.map((row) => (model.weight ? numberValue(row, model.weight) : 1));
  const fitted = fit(x, y, weights, params.tolerance);
  const stats = statistics(fitted, y, weights);
  const diagnostics = diagnose(fitted, x, stats.sigma, stats.df, params);
  return { model, rows, levels, columns, x, y, weights, fit: fitted, stats, diagnostics };
});
interface SubsetFit {
  fit: Fit;
  stats: Statistics;
}
function fitTerms(context: ModelContext, terms: number[]): SubsetFit {
  const columns = context.columns.flatMap((column, j) =>
    column.term === undefined || terms.includes(column.term) ? [j] : [],
  );
  const fitted = fit(
    context.x.map((row) => columns.map((j) => row[j])),
    context.y,
    context.weights,
    params.tolerance,
  );
  return { fit: fitted, stats: statistics(fitted, context.y, context.weights) };
}
interface MarginalTest {
  term: number;
  df: number;
  ss: number;
  rss: number;
  f?: number;
  p?: number;
}
function marginal(context: ModelContext, terms: number[], current: SubsetFit): MarginalTest[] {
  return terms
    .filter(
      (t) => !terms.some((other) => contained(context.model.terms[t], context.model.terms[other])),
    )
    .map((term) => {
      const reduced = fitTerms(
        context,
        terms.filter((t) => t !== term),
      );
      const df = current.fit.rank - reduced.fit.rank;
      const ss = reduced.fit.rss - current.fit.rss;
      const value = df > 0 ? ss / df / (current.fit.rss / current.stats.df) : undefined;
      return {
        term,
        df,
        ss,
        rss: reduced.fit.rss,
        f: value,
        p: value === undefined ? undefined : pF(value, df, current.stats.df),
      };
    });
}
interface TableRow {
  fields: string[];
  mark?: string;
}
interface Coefficient {
  name: string;
  estimate?: number;
  se?: number;
  t?: number;
  p?: number;
  lower?: number;
  upper?: number;
  robustSe?: number;
  robustT?: number;
  robustP?: number;
}
function table(header: string[], rows: TableRow[]): string[] {
  const widths = header.map((heading, c) =>
    Math.max(heading.length, ...rows.map((row) => row.fields[c]?.length ?? 0)),
  );
  const render = (fields: string[], mark = '') =>
    fields
      .map((field, c) => (c ? field.padStart(widths[c]) : field.padEnd(widths[c])))
      .join('  ')
      .trimEnd() + (mark ? ' ' + mark : '');
  return [render(header), ...rows.map((row) => render(row.fields, row.mark))];
}
const numericColumns = data.columns.filter((c) => !c.categorical);
const categoricalColumns = data.columns.filter((c) => c.categorical);
const summary = [
  `Data: ${data.rows.length} rows, ${data.columns.length} columns`,
  '',
  'Numeric columns:',
];
summary.push(
  ...table(
    ['column', 'n', 'missing', 'Mean', 'SD', 'Min', 'Max'],
    numericColumns.map((column) => {
      const values = data.rows
        .map((row) => row.values[column.name])
        .filter((value): value is number => typeof value === 'number');
      const mean = sum(values) / values.length;
      return {
        fields: [
          column.name,
          String(values.length),
          String(data.rows.length - values.length),
          f(mean),
          f(
            Math.sqrt(
              sum(values.map((value) => (value - mean) * (value - mean))) / (values.length - 1),
            ),
          ),
          f(Math.min(...values)),
          f(Math.max(...values)),
        ],
      };
    }),
  ),
  '',
  'Categorical columns:',
);
for (const column of categoricalColumns) {
  const values = data.rows
    .map((row) => row.values[column.name])
    .filter((value): value is string => typeof value === 'string');
  const levels = [...new Set(values)].sort();
  summary.push(
    `${column.name}: ${values.length} values, ${data.rows.length - values.length} missing, ${levels.length} levels: ${levels.map((level) => `${level} ${values.filter((value) => value === level).length}`).join(', ')}`,
  );
}
summary.push(
  '',
  'Correlations (pairwise complete observations):',
  ...table(
    ['column', ...numericColumns.map((c) => c.name)],
    numericColumns.map((a) => ({
      fields: [
        a.name,
        ...numericColumns.map((b) => {
          const pairs = data.rows.flatMap((row) => {
            const x = row.values[a.name];
            const y = row.values[b.name];
            return typeof x === 'number' && typeof y === 'number' ? [{ x, y }] : [];
          });
          const xbar = sum(pairs.map((pair) => pair.x)) / pairs.length;
          const ybar = sum(pairs.map((pair) => pair.y)) / pairs.length;
          let xy = 0;
          let xx = 0;
          let yy = 0;
          for (const pair of pairs) {
            xy += (pair.x - xbar) * (pair.y - ybar);
            xx += (pair.x - xbar) * (pair.x - xbar);
